package resolver

import (
	"context"
	"fmt"
	"net"
	"strings"
	"sync"
	"time"
)

type Role int

const (
	RoleGuest Role = iota
	RoleUser
	RoleAdmin
)

type AccessPolicy struct {
	AllowedZones []string
	MaxQPS       int
	CanResolveInternal bool
}

var policies = map[Role]AccessPolicy{
	RoleGuest: {AllowedZones: []string{".com", ".org", ".net"}, MaxQPS: 10, CanResolveInternal: false},
	RoleUser:  {AllowedZones: []string{".com", ".org", ".net", ".io", ".dev"}, MaxQPS: 100, CanResolveInternal: false},
	RoleAdmin: {AllowedZones: []string{"*"}, MaxQPS: 1000, CanResolveInternal: true},
}

type Session struct {
	mu       sync.Mutex
	UserID   string
	Role     Role
	resolved int
	lastReset time.Time
}

type ResolverService struct {
	sessions sync.Map
	cache    sync.Map
}

func NewResolverService() *ResolverService {
	return &ResolverService{}
}

func (rs *ResolverService) Authenticate(userID string, role Role) *Session {
	s := &Session{
		UserID:    userID,
		Role:      role,
		lastReset: time.Now(),
	}
	rs.sessions.Store(userID, s)
	return s
}

func (s *Session) checkRateLimit(policy AccessPolicy) bool {
	// mu is already held by caller
	if time.Since(s.lastReset) > time.Second {
		s.resolved = 0
		s.lastReset = time.Now()
	}
	if s.resolved >= policy.MaxQPS {
		return false
	}
	s.resolved++
	return true
}

// normalizeDomain normalizes a DNS name for consistent, case-insensitive
// comparison. DNS names are case-insensitive, so validation must operate on a
// canonical form to prevent access-control bypass.
func normalizeDomain(domain string) string {
	domain = strings.TrimSpace(domain)
	domain = strings.TrimSuffix(domain, ".")
	return strings.ToLower(domain)
}

func isInternalDomain(domain string) bool {
	return strings.HasSuffix(domain, ".internal") ||
		strings.HasSuffix(domain, ".corp") ||
		strings.HasSuffix(domain, ".local")
}

func (rs *ResolverService) validateAccess(session *Session, domain string) (*AccessPolicy, error) {
	// session.mu must be held by caller
	policy := policies[session.Role]

	if isInternalDomain(domain) && !policy.CanResolveInternal {
		return nil, fmt.Errorf("access denied: cannot resolve internal domain %s", domain)
	}

	if policy.AllowedZones[0] != "*" {
		allowed := false
		for _, zone := range policy.AllowedZones {
			if strings.HasSuffix(domain, zone) {
				allowed = true
				break
			}
		}
		if !allowed {
			return nil, fmt.Errorf("access denied: zone not allowed for role")
		}
	}

	return &policy, nil
}

func (rs *ResolverService) Resolve(ctx context.Context, userID string, domain string) ([]string, error) {
	val, ok := rs.sessions.Load(userID)
	if !ok {
		return nil, fmt.Errorf("session not found")
	}
	session := val.(*Session)

	// Normalize the domain once, up front, so all access checks, cache lookups
	// and the resolution itself operate on the same canonical value. This
	// prevents case-based bypass of the zone/internal restrictions.
	domain = normalizeDomain(domain)
	if domain == "" {
		return nil, fmt.Errorf("invalid domain")
	}

	// Hold lock for entire access check + rate limit to prevent TOCTOU
	session.mu.Lock()
	policy, err := rs.validateAccess(session, domain)
	if err != nil {
		session.mu.Unlock()
		return nil, err
	}

	if !session.checkRateLimit(*policy) {
		session.mu.Unlock()
		return nil, fmt.Errorf("rate limit exceeded")
	}
	session.mu.Unlock()

	// Check cache
	if cached, ok := rs.cache.Load(domain); ok {
		return cached.([]string), nil
	}

	// Perform resolution
	result, err := rs.doResolve(ctx, domain)
	if err != nil {
		return nil, err
	}

	rs.cache.Store(domain, result)
	return result, nil
}

func (rs *ResolverService) doResolve(ctx context.Context, domain string) ([]string, error) {
	resolver := &net.Resolver{
		PreferGo: true,
	}
	addrs, err := resolver.LookupHost(ctx, domain)
	if err != nil {
		return nil, fmt.Errorf("resolution failed: %w", err)
	}
	return addrs, nil
}

// UpdateRole allows changing a session's role (e.g., after re-authentication)
func (rs *ResolverService) UpdateRole(userID string, newRole Role) error {
	val, ok := rs.sessions.Load(userID)
	if !ok {
		return fmt.Errorf("session not found")
	}
	session := val.(*Session)
	session.mu.Lock()
	defer session.mu.Unlock()
	session.Role = newRole
	return nil
}

// DemoteUser is called when suspicious activity is detected
func (rs *ResolverService) DemoteUser(userID string) error {
	return rs.UpdateRole(userID, RoleGuest)
}
